for (size_t i = start; i < end; ++i) {
    Particle& p = particles[i];
    float density = 0.0f;

    int32_t cellX = static_cast<int32_t>(p.position.x / h);
    int32_t cellY = static_cast<int32_t>(p.position.y / h);
    int32_t cellZ = static_cast<int32_t>(p.position.z / h);

    for (int32_t x = cellX - 1; x <= cellX + 1; ++x) {
        for (int32_t y = cellY - 1; y <= cellY + 1; ++y) {
            for (int32_t z = cellZ - 1; z <= cellZ + 1; ++z) {
                uint32_t hash = (x * 73856093) ^ (y * 19349663) ^ (z * 83492791);
                hash %= particleCount;

                uint32_t index = particleTable[hash];
                while (index != 0xFFFFFFFF) {
                    if (index >= particleCount) break;
                    Particle& neighbor = particles[index];

                    float dx = p.position.x - neighbor.position.x;
                    float dy = p.position.y - neighbor.position.y;
                    float dz = p.position.z - neighbor.position.z;
                    float r2 = dx*dx + dy*dy + dz*dz;

                    if (r2 < h2) {
                        float r = std::sqrt(r2);
                        float ratio = 1.0f - (r / h);
                        float ratio2 = ratio * ratio;
                        float ratio6 = ratio2 * ratio2 * ratio2;
                        density += mass * poly6 * ratio6;
                    }

                    hash = (hash + 1) % particleCount;
                    index = particleTable[hash];
                }
            }
        }
    }

    density += selfDens;
    p.density = density;
    p.pressure = gasConstant * (density - restDensity);
}
// END_CODE

